import {buildIndex, normalize, searchEntries, getOccurrences, csv} from './engine.js';
const $=id=>document.getElementById(id), roman=['I','II','III','IV','V','VI','VII'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let corpus,index,start=1,selected='',formFilter='',limit=30,listLimit=60,size=17;
const scope=()=>Number($('scope').value), mode=()=>$('mode').value;
function selectedOccurrence(c,t){return selected && (mode()==='lemma'?t[2]===selected:normalize(c.la.slice(t[0],t[1]))===selected) && (!formFilter || normalize(c.la.slice(t[0],t[1]))===formFilter);}
function latin(c){let end=0,out=''; for(const [i,t] of c.tokens.entries()){out+=esc(c.la.slice(end,t[0]));out+=`<button class="word${selectedOccurrence(c,t)?' selected':''}" data-canon="${c.n}" data-token="${i}" title="${esc(t[2])} · ${esc(t[3])}${t[4]?' · '+esc(t[4]):''}" aria-label="${esc(c.la.slice(t[0],t[1]))}: explore ${esc(t[2])}">${esc(c.la.slice(t[0],t[1]))}</button>`;end=t[1];}return out+esc(c.la.slice(end));}
function renderReader(){const book=corpus.books.find(b=>b.start<=start&&b.end>=start),end=Math.min(start+4,book.end);$('bookLabel').textContent=`BOOK ${roman[book.id-1]} · CANONS ${book.start}–${book.end}`;$('bookTitle').textContent=book.en;$('bookLatin').textContent=book.la;$('canonInput').value=start;$('reader').innerHTML=corpus.canons.slice(start-1,end).map(c=>`<article class="canon" id="canon-${c.n}"><div class="canon-header"><span></span>CANON ${c.n}</div><div class="parallel"><div class="text" lang="la">${latin(c)}</div><div class="text english" lang="en">${c.enNote?`<span class="translation-note">${esc(c.enNote)}</span>`:""}${esc(c.en)}</div></div></article>`).join('');$('reader').ariaBusy='false';$('range').textContent=`Canons ${start}–${end} of 1,752`;$('previous').disabled=start===1;$('next').disabled=end===1752;$('next').dataset.start=end+1;document.querySelectorAll('.book-button').forEach(b=>b.classList.toggle('active',Number(b.dataset.book)===book.id));}
function go(n,scroll=true){if(!Number.isInteger(n)||n<1||n>1752)return;start=n;history.replaceState(null,'',`#canon=${n}`);try{localStorage.setItem('canon-reader-position',n)}catch{}renderReader();if(scroll)$('bookTitle').scrollIntoView({behavior:'smooth',block:'start'});}
function renderList(){selected='';formFilter='';const entries=searchEntries(index,$('wordSearch').value,scope(),mode());$('analysisContent').innerHTML=`<div class="section-label"><span>${$('wordSearch').value?'Search results':'Word frequency'}</span><span>${entries.length.toLocaleString()} ${mode()==='lemma'?'lemmas':'forms'}</span></div><p class="note">${mode()==='lemma'?'Conjugations and declensions counted together.':'Each Latin spelling counted separately.'} ${scope()?'Book '+roman[scope()-1]:'Across all seven books'}.</p><button class="export" id="exportFrequencies">↓ Export frequencies</button>${entries.slice(0,listLimit).map(e=>`<button class="entry" data-word="${esc(e.lemma)}"><span><span class="lemma">${esc(e.lemma)}</span><small>${new Set(e.occurrences.map(o=>o.form)).size} form${new Set(e.occurrences.map(o=>o.form)).size===1?'':'s'} · ${new Set(e.occurrences.map(o=>o.canon)).size} canons</small></span><span class="count">${e.occurrences.length.toLocaleString()} ↗</span></button>`).join('')}${!entries.length?'<div class="empty">No Latin matches in this scope. Try an inflected form or dictionary headword, or choose Entire Code.</div>':''}${entries.length>listLimit?'<button class="more" id="moreEntries">Show more words</button>':''}`;renderHighlights();}
function renderHighlights(){document.querySelectorAll('.word').forEach(el=>{const c=corpus.canons[Number(el.dataset.canon)-1];el.classList.toggle('selected',Boolean(selectedOccurrence(c,c.tokens[Number(el.dataset.token)])));});}
function renderDetail(){const all=getOccurrences(index,selected,scope(),mode()),occ=getOccurrences(index,selected,scope(),mode(),formFilter),forms=new Map();for(const o of all)forms.set(o.form,(forms.get(o.form)||0)+1);const groups=new Map();for(const o of occ){if(!groups.has(o.canon))groups.set(o.canon,[]);groups.get(o.canon).push(o);}const entry=index.lemmas.get(selected);$('analysisContent').innerHTML=`<button class="back" id="backToList">← Word frequency</button><div class="lemma-title"><h3 lang="la">${esc(selected)}</h3><span class="tag">${mode()==='lemma'?esc([...entry.pos].join(' · ')):'EXACT FORM'}</span></div><div class="metrics"><div><b>${occ.length.toLocaleString()}</b><small>OCCURRENCES</small></div><div><b>${groups.size.toLocaleString()}</b><small>CANONS</small></div><div><b>${forms.size}</b><small>FORMS</small></div></div><p class="note">${scope()?'Book '+roman[scope()-1]:'Entire Code'} · ${formFilter?'Showing “'+esc(formFilter)+'” only':mode()==='lemma'?'All inflections grouped':'Exact spelling only'}</p><div class="section-label"><span>Attested forms</span><span>Click to filter</span></div><div class="forms">${[...forms].sort((a,b)=>b[1]-a[1]).map(([f,n])=>`<button class="form-chip${f===formFilter?' active':''}" data-form="${esc(f)}">${esc(f)}<span>${n}</span></button>`).join('')}</div>${formFilter?'<button class="back" id="clearForm">× Show all forms</button>':''}<div class="section-label"><span>In context</span><button class="export" id="exportOccurrences">↓ CSV</button></div>${[...groups].slice(0,limit).map(([n,os])=>{const c=corpus.canons[n-1],first=os[0],left=Math.max(0,first.start-65),right=Math.min(c.la.length,first.end+115);let text='',cursor=left;for(const o of os.filter(o=>o.start>=left&&o.end<=right)){text+=esc(c.la.slice(cursor,o.start))+`<mark>${esc(c.la.slice(o.start,o.end))}</mark>`;cursor=o.end;}text+=esc(c.la.slice(cursor,right));return `<button class="occurrence" data-jump="${n}"><strong>CAN. ${n} <span>· BOOK ${roman[c.book-1]}${os.length>1?' · '+os.length+' uses':''}</span> ↗</strong><p lang="la">${left?'…':''}${text}${right<c.la.length?'…':''}</p></button>`;}).join('')}${!occ.length?'<p class="empty">No occurrences in this book. Select Entire Code to expand the search.</p>':''}${groups.size>limit?'<button class="more" id="moreOccurrences">Show more canons</button>':''}<p class="note">Lemmas are machine-predicted in context. Ambiguous forms can belong to more than one headword; counts reflect each token’s predicted lemma.</p>`;renderHighlights();}
function selectWord(w){selected=w;formFilter='';limit=30;renderDetail();$('analysisContent').scrollTop=0;}
function download(name,rows){const blob=new Blob(['\uFEFF'+csv(rows)],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function about(){const c=corpus.canons[start-1];$('aboutContent').innerHTML=`<p>This reader contains all <strong>1,752 canons</strong> of the 1983 Code for the Latin Church, aligned by canon number.</p><h3>Source texts</h3><p>Imported from the Vatican’s <a href="https://www.vatican.va/archive/cod-iuris-canonici/cic_index_la.html" target="_blank" rel="noopener">Latin edition</a> and <a href="https://www.vatican.va/archive/cod-iuris-canonici/cic_index_en.html" target="_blank" rel="noopener">English translation</a> on ${esc(corpus.meta.retrieved)}. Text rights remain with their respective owners. Canons 111, 112, and 868 have clearly marked study translations supplied for this reader where the English source includes Latin amendments.</p><p>${esc(corpus.meta.edition)} The displayed texts retain the wording of those source pages, including any source typographical errors.</p><p>View this passage at its source: <a href="${esc(c.laSource)}" target="_blank" rel="noopener">Latin</a> · <a href="${esc(c.enSource)}" target="_blank" rel="noopener">English</a>.</p><h3>Latin word families</h3><p>${esc(corpus.meta.lemmaNote)} Explicit noun mappings improve grouping of common canon-law terms; the remaining lemmas and grammatical features are predictions. The model is <a href="https://huggingface.co/latincy/la_core_web_sm" target="_blank" rel="noopener">${esc(corpus.meta.model)}</a>. Hover over a Latin word to inspect its lemma, part of speech, and morphology.</p><p>Counts use only the Latin canon text, excluding canon labels, headings, and numbers. LatinCy may split enclitics into separate tokens. Capitalization and macrons are ignored; j is normalized to i. Every token is assigned one predicted lemma, so ambiguous spellings can appear under multiple headwords. Exact forms mode combines their spelling counts.</p><p>Click a form to narrow a word family. Scope filters affect frequencies and concordance results. CSV exports include the complete filtered result, including rows beyond the visible list. Processing and searching happen locally in your browser.</p>`;$('about').showModal();}
async function init(){try{const response=await fetch('./data/corpus.json');if(!response.ok)throw new Error('Corpus request failed');corpus=await response.json();index=buildIndex(corpus);$('books').innerHTML=corpus.books.map(b=>`<button class="book-button" data-book="${b.id}" data-start="${b.start}"><span class="roman">${roman[b.id-1]}</span><span>${esc(b.en)}<small>CANONS ${b.start}–${b.end}</small></span></button>`).join('');$('scope').insertAdjacentHTML('beforeend',corpus.books.map(b=>`<option value="${b.id}">Book ${roman[b.id-1]} · ${esc(b.en)}</option>`).join(''));let saved=1;try{saved=Number(localStorage.getItem('canon-reader-position'))||1}catch{}const hash=Number(new URLSearchParams(location.hash.slice(1)).get('canon'));go(hash||saved,false);renderList();
$('books').addEventListener('click',e=>{const b=e.target.closest('[data-start]');if(b)go(Number(b.dataset.start));});$('jumpForm').addEventListener('submit',e=>{e.preventDefault();go(Number($('canonInput').value));});$('previous').onclick=()=>go(Math.max(1,start-5));$('next').onclick=()=>go(Number($('next').dataset.start));$('reader').onclick=e=>{const el=e.target.closest('.word');if(!el)return;const c=corpus.canons[Number(el.dataset.canon)-1],t=c.tokens[Number(el.dataset.token)];selectWord(mode()==='lemma'?t[2]:normalize(c.la.slice(t[0],t[1])));if(innerWidth<=760)document.querySelector('.analysis').scrollIntoView({behavior:'smooth'});};$('wordSearch').oninput=()=>{listLimit=60;renderList();};$('scope').onchange=()=>{formFilter='';limit=30;selected?renderDetail():renderList();};$('mode').onchange=()=>{listLimit=60;renderList();};$('analysisContent').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.word)selectWord(b.dataset.word);else if(b.dataset.form){formFilter=formFilter===b.dataset.form?'':b.dataset.form;limit=30;renderDetail();}else if(b.dataset.jump)go(Number(b.dataset.jump));else if(b.id==='backToList')renderList();else if(b.id==='clearForm'){formFilter='';renderDetail();}else if(b.id==='moreOccurrences'){limit+=30;renderDetail();}else if(b.id==='moreEntries'){listLimit+=60;renderList();}else if(b.id==='exportFrequencies')download('latin-frequencies.csv',[['Latin '+mode(),'Occurrences','Canons','Scope'],...searchEntries(index,$('wordSearch').value,scope(),mode()).map(e=>[e.lemma,e.occurrences.length,new Set(e.occurrences.map(o=>o.canon)).size,scope()||'Entire Code'])]);else if(b.id==='exportOccurrences')download('latin-'+selected+'.csv',[['Lemma / form','Canon','Book','Form','Latin canon','English canon'],...getOccurrences(index,selected,scope(),mode(),formFilter).map(o=>[selected,o.canon,o.book,o.form,corpus.canons[o.canon-1].la,corpus.canons[o.canon-1].en])]);};$('smaller').onclick=()=>{size=Math.max(13,size-1);document.documentElement.style.setProperty('--reading-size',size+'px');};$('larger').onclick=()=>{size=Math.min(24,size+1);document.documentElement.style.setProperty('--reading-size',size+'px');};$('aboutButton').onclick=about;$('methodButton').onclick=about;$('closeAbout').onclick=()=>$('about').close();window.addEventListener('hashchange',()=>go(Number(new URLSearchParams(location.hash.slice(1)).get('canon'))||1));
}catch(error){console.error(error);$('reader').innerHTML='<div class="loading">The text could not be loaded. Please refresh, or run this folder with <code>npm start</code> and open http://localhost:8080.</div>';$('analysisContent').textContent='Latin index unavailable.';$('reader').ariaBusy='false';}}
init();
